const mustNotCallTools = [];
const mustNotModifyFiles = ["tests/","src/"];

let score = 1.0;
const reasons = [];

if (mustCallTools.length > 0) {
  const hits = mustCallTools.filter(function(t) { return toolsUsed.includes(t); });
  if (mustCallMode === "any_of") {
    // any_of：命中任一即满分；一个都没命中扣 0.4
    if (hits.length === 0) {
