    score: 1.0,
    reason: "sideband metadata 缺失（trajectory 未落盘或读取失败），跳过工具合规检查",
  };
}

score = Math.max(0, score);
return {
  pass: score >= 0.6,
  score,
  reason: reasons.length > 0 ? reasons.join("; ") : "工具使用合规",
};


