    // all_of（默认）：按命中比例扣分
    if (hits.length < mustCallTools.length) {
      score -= 0.4 * (1 - hits.length / mustCallTools.length);
      reasons.push("未使用要求的工具: " + mustCallTools.filter(function(t) { return !toolsUsed.includes(t); }).join(", "));
    }
  }
